/**
 * Inter (latin subset) embedded as data URIs, for documents rendered in a locked-down browser that may load nothing
 * but data: URIs (the market report PDF: htmlToPdf lockdown).
 *
 * Without it the PDF used whatever font the rendering machine had: Open Sans regular + bold on production's
 * serverless Chromium, Inter in cloud sessions, DejaVu or Liberation on CI, so the same report printed 6 or 7 pages
 * depending on the machine (Design & Output, Track C2, 2026-11-23).
 *
 * Three STATIC weights, 400, 600 and 800 (the weights the report's CSS asks for), cut from the app's own self-hosted variable file
 * (public/fonts/app/v1/inter-latin-wght-normal.woff2, SIL OFL 1.1, see public/fonts/app/v1/LICENSES) with fontTools:
 *   instancer.instantiateVariableFont(font, {'wght': 400 | 600 | 800}); flavor 'woff2'
 * Static, because Chromium turns a variable web font into Type 3 fonts in a PDF (poor text extraction and rendering in
 * some viewers, +190 KB). Three weights keep the page under ~100 KB; 700
 * (bold text, headings) resolves to 800. Glyphs outside the latin subset (e.g. "←") still fall
 * back to a system font.
 */
export const INTER_LATIN_400_WOFF2_BASE64 =
  '';

export const INTER_LATIN_600_WOFF2_BASE64 =
  '';

export const INTER_LATIN_800_WOFF2_BASE64 =
  '';

/** @font-face rules naming the embedded files "Mindy Report Inter" at 400, 600 and 800. A name of its own, so a machine with
 *  Inter installed locally can never substitute its own copy (cloud sessions do; production does not). */
export const INTER_LATIN_FONT_FACE = ([
  [400, INTER_LATIN_400_WOFF2_BASE64],
  [600, INTER_LATIN_600_WOFF2_BASE64],
  [800, INTER_LATIN_800_WOFF2_BASE64],
] as const).map(([w, b64]) => `@font-face{font-family:'Mindy Report Inter';font-style:normal;font-weight:${w};font-display:block;src:url(data:font/woff2;base64,${b64}) format('woff2');}`).join('');
